-- 03_dw.sql
USE DATABASE CRICKET_ANALYTICS;
CREATE TABLE IF NOT EXISTS DW.DIM_DATE (SK_DATE NUMBER AUTOINCREMENT PRIMARY KEY, DATE_VALUE DATE UNIQUE, YEAR NUMBER, QUARTER NUMBER, MONTH NUMBER, MONTH_NAME VARCHAR, WEEK_OF_YEAR NUMBER, DAY_OF_MONTH NUMBER, DAY_NAME VARCHAR, IS_WEEKEND BOOLEAN);
CREATE TABLE IF NOT EXISTS DW.DIM_TEAM (SK_TEAM NUMBER AUTOINCREMENT PRIMARY KEY, TEAM_ID VARCHAR UNIQUE, TEAM_NAME VARCHAR, TEAM_CODE VARCHAR, COUNTRY VARCHAR, COMPETITION VARCHAR, REGION VARCHAR, ESTABLISHED_DATE DATE, STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS DW.DIM_VENUE (SK_VENUE NUMBER AUTOINCREMENT PRIMARY KEY, VENUE_ID VARCHAR UNIQUE, VENUE_NAME VARCHAR, CITY VARCHAR, STATE VARCHAR, COUNTRY VARCHAR, REGION VARCHAR, STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS DW.DIM_PLAYER (SK_PLAYER NUMBER AUTOINCREMENT PRIMARY KEY, PLAYER_ID VARCHAR, FIRST_NAME VARCHAR, LAST_NAME VARCHAR, NATIONALITY VARCHAR, BATTING_STYLE VARCHAR, BOWLING_STYLE VARCHAR, ROLE VARCHAR, CURRENT_TEAM_ID VARCHAR, STATUS VARCHAR, HASH_DIFF VARCHAR, EFF_START_TS TIMESTAMP_LTZ, EFF_END_TS TIMESTAMP_LTZ, IS_CURRENT BOOLEAN);
CREATE TABLE IF NOT EXISTS DW.DIM_MATCH (SK_MATCH NUMBER AUTOINCREMENT PRIMARY KEY, MATCH_ID VARCHAR UNIQUE, COMPETITION VARCHAR, FORMAT VARCHAR, MATCH_DATE DATE, SK_DATE NUMBER, VENUE_ID VARCHAR, SK_VENUE NUMBER, TEAM_A_ID VARCHAR, SK_TEAM_A NUMBER, TEAM_B_ID VARCHAR, SK_TEAM_B NUMBER, TOSS_WINNER_TEAM_ID VARCHAR, WINNER_TEAM_ID VARCHAR, RESULT_TYPE VARCHAR, RESULT_MARGIN NUMBER, MATCH_STATUS VARCHAR);
CREATE TABLE IF NOT EXISTS DW.FACT_DELIVERY (DELIVERY_ID VARCHAR PRIMARY KEY, SK_DATE NUMBER, SK_MATCH NUMBER, SK_VENUE NUMBER, SK_BATTING_TEAM NUMBER, SK_BOWLING_TEAM NUMBER, SK_STRIKER NUMBER, SK_NON_STRIKER NUMBER, SK_BOWLER NUMBER, INNINGS_NO NUMBER, OVER_NO NUMBER, BALL_NO NUMBER, OVER_PHASE VARCHAR, BATSMAN_RUNS NUMBER, WIDES NUMBER, NO_BALLS NUMBER, BYES NUMBER, LEG_BYES NUMBER, TOTAL_RUNS NUMBER, IS_WICKET NUMBER, DISMISSAL_TYPE VARCHAR, IS_FOUR NUMBER, IS_SIX NUMBER, IS_DOT_BALL NUMBER, LOAD_TS TIMESTAMP_LTZ, BATCH_ID VARCHAR);

INSERT INTO DW.DIM_TEAM(TEAM_ID,TEAM_NAME,STATUS) SELECT 'UNKNOWN','Unknown','UNKNOWN' WHERE NOT EXISTS(SELECT 1 FROM DW.DIM_TEAM WHERE TEAM_ID='UNKNOWN');
INSERT INTO DW.DIM_VENUE(VENUE_ID,VENUE_NAME,STATUS) SELECT 'UNKNOWN','Unknown','UNKNOWN' WHERE NOT EXISTS(SELECT 1 FROM DW.DIM_VENUE WHERE VENUE_ID='UNKNOWN');
INSERT INTO DW.DIM_PLAYER(PLAYER_ID,FIRST_NAME,LAST_NAME,STATUS,HASH_DIFF,EFF_START_TS,EFF_END_TS,IS_CURRENT) SELECT 'UNKNOWN','Unknown','','UNKNOWN',MD5('UNKNOWN'),'1900-01-01'::TIMESTAMP_LTZ,'9999-12-31'::TIMESTAMP_LTZ,TRUE WHERE NOT EXISTS(SELECT 1 FROM DW.DIM_PLAYER WHERE PLAYER_ID='UNKNOWN' AND IS_CURRENT=TRUE);
INSERT INTO DW.DIM_DATE(DATE_VALUE,YEAR,QUARTER,MONTH,MONTH_NAME,WEEK_OF_YEAR,DAY_OF_MONTH,DAY_NAME,IS_WEEKEND) SELECT '1900-01-01',1900,1,1,'January',1,1,'Monday',FALSE WHERE NOT EXISTS(SELECT 1 FROM DW.DIM_DATE WHERE DATE_VALUE='1900-01-01');
INSERT INTO DW.DIM_MATCH(MATCH_ID,MATCH_STATUS) SELECT 'UNKNOWN','UNKNOWN' WHERE NOT EXISTS(SELECT 1 FROM DW.DIM_MATCH WHERE MATCH_ID='UNKNOWN');
